target.handler:
aiGenerating = true; aiMsg = '';
Platform.fetch.post('/solutions/{{ solution.id }}/generate-draft', {problem_statement: '{{ (solution.description or solution.name)|replace("'", "\\'") }}'}, { silent: true })
.then(d => {
    aiSuccess = d.success;
    aiMsg = d.success ? 'Created ' + (d.total || 0) + ' entities — reloading...' : (d.error || 'Failed');
    if (d.success) setTimeout(() => window.location.reload(), 1800);
})
.catch(e => { aiMsg = (e && e.message) || 'Failed'; aiSuccess = false; })
.finally(() => { aiGenerating = false; })
